/**
 * @summary Get the Stripe subscription for a given owner (studentId for solo, teacherId for organization)
 */
export const getGetSubscriptionUrl = (params: GetSubscriptionParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/billing/subscription?${stringifiedParams}`
    : `/api/billing/subscription`;
};

export const getSubscription = async (
  params: GetSubscriptionParams,
  options?: RequestInit,
): Promise<Subscription> => {
  return customFetch<Subscription>(getGetSubscriptionUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getGetSubscriptionQueryKey = (params?: GetSubscriptionParams) => {
  return [`/api/billing/subscription`, ...(params ? [params] : [])] as const;
};

export const getGetSubscriptionQueryOptions = <
  TData = Awaited<ReturnType<typeof getSubscription>>,
  TError = ErrorType<void>,
>(
  params: GetSubscriptionParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getSubscription>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetSubscriptionQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getSubscription>>> = ({
    signal,
  }) => getSubscription(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof getSubscription>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetSubscriptionQueryResult = NonNullable<
  Awaited<ReturnType<typeof getSubscription>>
>;
export type GetSubscriptionQueryError = ErrorType<void>;

